(7196511, 1106535, 37392, '<td valign="top">great colors!<br/>it is in my top 5!! <br/> 9!!</td>', 'great colors!it is in my top 5!!  9!!', '2014-03-31 17:03:11.000000', NULL, 1),
(7196513, 1106865, 173844, '<td valign="top">A sublime image dominated by this magical structure backed by sunset clouds suffused in pink, orange and purple. The blue mountains and green trees offer  a sturdy backdrop.  Enchanting.  A slightly shifted perspective might have given the spire on the lower dome some separation from the foliage.</td>', 'A sublime image dominated by this magical structure backed by sunset clouds suffused in pink, orange and purple. The blue mountains and green trees offer  a sturdy backdrop.  Enchanting.  A slightly shifted perspective might have given the spire on the lower dome some separation from the foliage.', '2014-03-31 17:03:34.000000', NULL, 1),
(7196520, 1106983, 173844, '<td valign="top">I admire how you''ve been able to transmute what at first sight are ugly sources of pollution into whimsical "cloud machines."  The field of flowers is a lovely catalyst in your sleight of hand.  The man-made discharge fuses with the cloud cover rather elegantly.  The sensor spots are unfortunate.  Nevertheless, I''m putting this eye-opening picture into my favorites.</td>', 'I admire how you''ve been able to transmute what at first sight are ugly sources of pollution into whimsical "cloud machines."  The field of flowers is a lovely catalyst in your sleight of hand.  The man-made discharge fuses with the cloud cover rather elegantly.  The sensor spots are unfortunate.  Nevertheless, I''m putting this eye-opening picture into my favorites.', '2014-03-31 17:15:33.000000', NULL, 1),
(7196535, 1106535, 22970, '<td valign="top">The fence in the foreground adds a nice touch to landscape. The clouds are dramatic. Great photo.</td>', 'The fence in the foreground adds a nice touch to landscape. The clouds are dramatic. Great photo.', '2014-03-31 17:41:40.000000', NULL, 1),
(7196536, 1106989, 22970, '<td valign="top">Looks like a great place to go and think. Nice photograph.</td>', 'Looks like a great place to go and think. Nice photograph.', '2014-03-31 17:42:58.000000', NULL, 1),
(7196537, 1106985, 22970, '<td valign="top">Nice clouds.</td>', 'Nice clouds.', '2014-03-31 17:45:05.000000', NULL, 1),
(7196539, 1106993, 22970, '<td valign="top">Beautiful place. Nice photo.</td>', 'Beautiful place. Nice photo.', '2014-03-31 17:46:21.000000', NULL, 1),
(7196541, 1106966, 22970, '<td valign="top">Wild perspective with dramatic clouds.</td>', 'Wild perspective with dramatic clouds.', '2014-03-31 17:47:28.000000', NULL, 1),
(7196543, 1106967, 22970, '<td valign="top">Nice photo with great color, motion, clouds, reflections. I really like the shot but wish the driftwood was not in the shot. With that said it did not affect my vote. Great capture.</td>', 'Nice photo with great color, motion, clouds, reflections. I really like the shot but wish the driftwood was not in the shot. With that said it did not affect my vote. Great capture.', '2014-03-31 17:50:17.000000', NULL, 1),
(7196546, 1106877, 22970, '<td valign="top">Nice shot with a good score, however, I would have like to of seen a foreground subject. A lot open space on the lower third of your photo.</td>', 'Nice shot with a good score, however, I would have like to of seen a foreground subject. A lot open space on the lower third of your photo.', '2014-03-31 17:52:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7196547, 1106634, 22970, '<td valign="top">Love the way you captured the sun rays coming through the clouds. Nice black and white. Good job.</td>', 'Love the way you captured the sun rays coming through the clouds. Nice black and white. Good job.', '2014-03-31 17:54:03.000000', NULL, 1),
(7196550, 1106988, 22970, '<td valign="top">Nice smooth and colorful photo. Long exposure worked well here.</td>', 'Nice smooth and colorful photo. Long exposure worked well here.', '2014-03-31 17:55:35.000000', NULL, 1),
(7196551, 1107013, 22970, '<td valign="top">Beautiful sky nicely balanced with the water and waves. Bump +1 during commenting.</td>', 'Beautiful sky nicely balanced with the water and waves. Bump +1 during commenting.', '2014-03-31 17:57:06.000000', NULL, 1),
(7196557, 1107021, 22970, '<td valign="top">My eyes roll from the plains up to the clouds with ease and back down to the white caped mountains. Very nice photo. Bump +1 during commenting.</td>', 'My eyes roll from the plains up to the clouds with ease and back down to the white caped mountains. Very nice photo. Bump +1 during commenting.', '2014-03-31 18:03:27.000000', NULL, 1),
(7196560, 1106991, 22970, '<td valign="top">The clouds are not as dramatic as some photos but works well withing yours. A nicely balance photo where the sky and clouds does not overpower the landscape and vice versa. Smooth and warm with and the sun could have not been in a better position. Bump +3 during commenting.</td>', 'The clouds are not as dramatic as some photos but works well withing yours. A nicely balance photo where the sky and clouds does not overpower the landscape and vice versa. Smooth and warm with and the sun could have not been in a better position. Bump +3 during commenting.', '2014-03-31 18:05:28.000000', NULL, 1),
(7196614, 1106986, 174999, '<td valign="top">Very dramatic and cool pic..spots are able to be seen</td>', 'Very dramatic and cool pic..spots are able to be seen', '2014-03-31 21:44:58.000000', NULL, 1),
(7196615, 1107025, 174999, '<td valign="top">Love the mountains and any pictures! Nice pic!</td>', 'Love the mountains and any pictures! Nice pic!', '2014-03-31 21:46:52.000000', NULL, 1),
(7196617, 1106989, 174999, '<td valign="top">I need to go here for vacation! Very relaxing to look at!</td>', 'I need to go here for vacation! Very relaxing to look at!', '2014-03-31 21:48:17.000000', NULL, 1),
(7196661, 1106916, 174999, '<td valign="top">Cool pic, noticed the spots</td>', 'Cool pic, noticed the spots', '2014-03-31 22:28:04.000000', NULL, 1),
(7196663, 1106884, 174999, '<td valign="top">pretty sunset!!!</td>', 'pretty sunset!!!', '2014-03-31 22:29:12.000000', NULL, 1),
(7196837, 1106535, 174999, '<td valign="top">This is soo pretty! This would have done well for the fence contest too! LOL<br/> <br/>Nice job</td>', 'This is soo pretty! This would have done well for the fence contest too! LOL Nice job', '2014-04-01 09:55:53.000000', NULL, 1),
(7196838, 1106983, 174999, '<td valign="top">I really loved the flowers in the field for this picture and the composition....<br/>spots were to be seen</td>', 'I really loved the flowers in the field for this picture and the composition....spots were to be seen', '2014-04-01 09:57:17.000000', NULL, 1),
(7196964, 1106961, 173844, '<td valign="top">Usually a gritty city-scape is contrasted with a lovely, fresh, ethereal sky,  but here that formula is confounded by extending the grittiness into that very sky.  And it works quite well, in conjunction with a balanced composition and an interesting set of clouds.  The dark cloud to the right -- which is hopefully not a swarm of locusts -- of course sets the tone, setting up both balance and dichotomy.  Interesting and rewarding.</td>', 'Usually a gritty city-scape is contrasted with a lovely, fresh, ethereal sky,  but here that formula is confounded by extending the grittiness into that very sky.  And it works quite well, in conjunction with a balanced composition and an interesting set of clouds.  The dark cloud to the right -- which is hopefully not a swarm of locusts -- of course sets the tone, setting up both balance and dichotomy.  Interesting and rewarding.', '2014-04-01 15:26:40.000000', NULL, 1),
(7196966, 1106772, 173844, '<td valign="top">A very pretty panorama with a huge bank of lowering clouds.  When you look closely at the clouds you notice the complexity, nuanced contrasts and rather off-white coloration.  It''s really a fine study.  And the clouds echoes are found in the shallows and the tumbling breakers.</td>', 'A very pretty panorama with a huge bank of lowering clouds.  When you look closely at the clouds you notice the complexity, nuanced contrasts and rather off-white coloration.  It''s really a fine study.  And the clouds echoes are found in the shallows and the tumbling breakers.', '2014-04-01 15:39:19.000000', NULL, 1),
(7196970, 1106898, 173844, '<td valign="top">This gentle image has a lot to offer.  The centered hilltop contributes to a sense of partial symmetry that''s nudged aside by the varying corona and distribution of stars.  The arrayed clouds transition subtly into the night sky assisted by a spectral fringe.  It doesn''t shout, it whispers.</td>', 'This gentle image has a lot to offer.  The centered hilltop contributes to a sense of partial symmetry that''s nudged aside by the varying corona and distribution of stars.  The arrayed clouds transition subtly into the night sky assisted by a spectral fringe.  It doesn''t shout, it whispers.', '2014-04-01 15:49:37.000000', NULL, 1),
(7196976, 1107021, 173844, '<td valign="top">The lower third of this picture is graphically strong with its receding plains, foothills and mountains, which provides a strong base for the more nebulous cloud system of the upper two thirds. It''s a nice study in contrast.  The clouds themselves are diversified enough to engage the viewer''s interest.  Handsome.</td>', 'The lower third of this picture is graphically strong with its receding plains, foothills and mountains, which provides a strong base for the more nebulous cloud system of the upper two thirds. It''s a nice study in contrast.  The clouds themselves are diversified enough to engage the viewer''s interest.  Handsome.', '2014-04-01 16:05:57.000000', NULL, 1),
(7196986, 1106719, 173844, '<td valign="top">An impressive and beautiful array of clouds that holds the viewer''s full attention above the almost silhouetted mesa.  A real feeling of immensity.</td>', 'An impressive and beautiful array of clouds that holds the viewer''s full attention above the almost silhouetted mesa.  A real feeling of immensity.', '2014-04-01 16:18:16.000000', NULL, 1),
(7196997, 1106482, 173844, '<td valign="top">The interest in this plain and interesting image is the wispy line of cloud two thirds up.  It''s tantalizingly close to disappearing, winking into and out of existence as the eye wanders about.  This effect is aided by the overall blue coloration.</td>', 'The interest in this plain and interesting image is the wispy line of cloud two thirds up.  It''s tantalizingly close to disappearing, winking into and out of existence as the eye wanders about.  This effect is aided by the overall blue coloration.', '2014-04-01 16:28:20.000000', NULL, 1),
(7197006, 1106962, 173844, '<td valign="top">The arching buildings nicely frame this scene.  The sunset display is magnificent, spanning the flashy colors on the left to the nighttime clouds on the right, unrolling like a Chinese scroll.  The sprawl is the sprawl.</td>', 'The arching buildings nicely frame this scene.  The sunset display is magnificent, spanning the flashy colors on the left to the nighttime clouds on the right, unrolling like a Chinese scroll.  The sprawl is the sprawl.', '2014-04-01 16:38:20.000000', NULL, 1),
(7197013, 1106622, 173844, '<td valign="top">A genial landscape that displays a generous and pretty assortment of atmospheric phenomena.  The crepuscular rays are lovely, as are the wispy cirri.</td>', 'A genial landscape that displays a generous and pretty assortment of atmospheric phenomena.  The crepuscular rays are lovely, as are the wispy cirri.', '2014-04-01 16:44:38.000000', NULL, 1),
(7197026, 1107007, 173844, '<td valign="top">A joyous, impressionistic image with a startling pink sweatshirt, which works fine and even has a distant echo in the soft rose tones in the sky.  The clouds have an after the storm feel.</td>', 'A joyous, impressionistic image with a startling pink sweatshirt, which works fine and even has a distant echo in the soft rose tones in the sky.  The clouds have an after the storm feel.', '2014-04-01 17:00:18.000000', NULL, 1),
(7197029, 1106932, 173844, '<td valign="top">An ominous, futuristic image of an evil corporate entity bent on global domination, like, maybe, Ben &amp; Jerry''s.</td>', 'An ominous, futuristic image of an evil corporate entity bent on global domination, like, maybe, Ben & Jerry''s.', '2014-04-01 17:07:15.000000', NULL, 1),
(7197030, 1107012, 173844, '<td valign="top">Beautiful image.  I like how the complicated cloud structure is simplified in the reflection on the water.</td>', 'Beautiful image.  I like how the complicated cloud structure is simplified in the reflection on the water.', '2014-04-01 17:10:24.000000', NULL, 1),
(7197032, 1106966, 173844, '<td valign="top">Dramatic, atmospheric image that is nicely toned and composed.  Wonderful study.</td>', 'Dramatic, atmospheric image that is nicely toned and composed.  Wonderful study.', '2014-04-01 17:13:21.000000', NULL, 1),
(7197069, 1106961, 58634, '<td valign="top">My top pick for this challenge. It''s different and has a dark, eerie feeling that I love. Also, the grainy aspect of it adds a lot of personality.</td>', 'My top pick for this challenge. It''s different and has a dark, eerie feeling that I love. Also, the grainy aspect of it adds a lot of personality.', '2014-04-01 18:09:59.000000', NULL, 1),
